// ============================================================================
// 3. 2026년 5·7급 승진 기출 복원 & 2027 교정 6급 실전 모의고사 3회분 (총 150문항 전수 수록)
// ============================================================================
function makeQ(
  examSetId: ExamQuestion['examSetId'],
  questionNumber: number,
  category: string,
  sourceTag: string,
  questionStem: string,
  answerNumber: 1 | 2 | 3 | 4,
  c1: [string, string],
  c2: [string, string],
  c3: [string, string],
  c4: [string, string],
  corePrincipleTitle: string,
  whyYouMissedIt: string,
  oneLineVaccine: string,
  relatedModuleId: string
): ExamQuestion {
  return {
    id: `${examSetId}-q${questionNumber}`,
    examSetId,
    questionNumber,
    category,
    sourceTag,
    questionStem,
    choices: [
      { num: 1, text: c1[0], isCorrectAnswer: answerNumber === 1, whyOptionExplanation: c1[1] },
      { num: 2, text: c2[0], isCorrectAnswer: answerNumber === 2, whyOptionExplanation: c2[1] },
      { num: 3, text: c3[0], isCorrectAnswer: answerNumber === 3, whyOptionExplanation: c3[1] },
      { num: 4, text: c4[0], isCorrectAnswer: answerNumber === 4, whyOptionExplanation: c4[1] },
    ],
    answerNumber,
    prescription: {
      corePrincipleTitle,
      whyYouMissedIt,
      oneLineVaccine,
      relatedModuleId,
    },
  };
}

