    '사형의 집행 명령·정지 명령·재집행 명령은 모두 법무부장관의 권한이고, 징역·금고·구류 등 자유형의 집행정지는 검사의 지휘(임의적 정지는 고검장·지검장 허가)에 의한다.',
    '사형 집행·정지·재개 = 모두 법무부장관 명령! 사형집행조서 작성자 = 검찰청 서기!',
