    '피고인의 특정과 소송능력에 관한 설명으로 가장 적절하지 않은 것은? (다툼이 있는 경우 판례에 의함)',
    1,
    ['갑이 을의 성명을 모용하여 공소장에 피고인으로 을이 표시된 경우, 검사는 법원의 허가를 얻어 공소장변경 절차를 거쳐야만 피고인의 표시를 갑으로 정정할 수 있다.', '틀림(정답). 성명모용의 경우 실질적 피고인은 처음부터 모용자 갑이므로, 검사는 법원의 허가를 요하는 공소장변경 절차를 거칠 필요 없이 서면으로 『피고인 표시정정』을 함으로써 족합니다.'],
    ['피고인이 법인인 때에는 대표자가 소송행위를 대표하며, 수인이 공동하여 법인을 대표하는 경우에도 소송행위에 관하여는 각자가 대표한다.', '옳음. 제27조제1항·제2항 조문입니다.'],
    ['형법 제9조부터 제11조까지(책임능력)의 규정이 적용되지 아니하는 범죄사건에 관하여 피고인 또는 피의자가 의사능력이 없는 때에는 법정대리인이 소송행위를 대리한다.', '옳음. 제26조 조문 그대로입니다.'],
    ['피고인이 심신상실의 상태에 있는 때에는 검사와 변호인의 의견을 들어 결정으로 그 상태가 계속하는 기간 공판절차를 정지하여야 하나, 무죄·면소·형의 면제 또는 공소기각의 재판을 할 것이 명백한 때에는 피고인의 출정 없이 재판할 수 있다.', '옳음. 제306조제1항·제4항 조문입니다.'],
    '성명모용(표시정정 O, 공소장변경 불요) 및 의사무능력자 소송절차 정지(제306조)',
    '성명모용에서 피고인은 모용자이므로 피고인이 바뀌는 것이 아니라 이름표만 고치는 것이어서 공소장변경 허가가 필요 없다.',
    '성명모용 피고인 표시정정 = 공소장변경 불요! 법인 공동대표 = 소송행위는 각자 대표(제27조제2항)!',
    'module2'
