    '일반 소송기간(상소기간 7일, 항소이유서 20일 등)은 초일을 산입하지 않고 말일이 공휴일이면 다음 날로 연장되지만, 피고인에게 불리해지는 "공소시효"와 "구속기간"은 초일을 1일로 산입하고 말일이 공휴일이어도 연장되지 않는다.',
